pm.test("Status code harus 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response harus berupa JSON", function () {
    pm.response.to.be.json;
});

const response = pm.response.json();

pm.test("Response memiliki bookingid", function () {
    pm.expect(response).to.have.property("bookingid");
});

pm.test("Booking ID harus berupa angka", function () {
    pm.expect(response.bookingid).to.be.a("number");
});

pm.test("Response memiliki objek booking", function () {
    pm.expect(response).to.have.property("booking");
    pm.expect(response.booking).to.be.an("object");
});

pm.test("Data booking sesuai dengan request", function () {
    pm.expect(response.booking.firstname).to.eql("Aksal");
    pm.expect(response.booking.lastname).to.eql("Pratama");
    pm.expect(response.booking.totalprice).to.eql(150000);
    pm.expect(response.booking.depositpaid).to.eql(true);
    pm.expect(response.booking.bookingdates.checkin).to.eql("2026-11-10");
    pm.expect(response.booking.bookingdates.checkout).to.eql("2026-11-15");
    pm.expect(response.booking.additionalneeds).to.eql("Breakfast");
});

//simpan booking ID untuk pengujian berikutnya
if (
    pm.response.code === 200 &&
    typeof response.bookingid === "number"
) {
    pm.environment.set("bookingId", response.bookingid);
    console.log("Booking ID berhasil disimpan.");
}

pm.test("Status code menunjukkan server error", function () {
    pm.response.to.have.status(500);
});

pm.test("Response berupa plain text", function () {
    pm.expect(pm.response.text()).to.eql("Internal Server Error");
});

pm.test("Response tidak mengandung booking ID", function () {
    pm.expect(pm.response.text()).to.not.include("bookingid");
});

pm.test("Status code menunjukkan respons HTTP", function () {
    pm.expect(pm.response.code).to.be.a("number");
});

pm.test("Response memiliki format JSON", function () {
