});

const response = pm.response.json();

pm.test("Response tidak boleh menghasilkan booking ID", function () {
    pm.expect(response).to.not.have.property("bookingid");
});

pm.test("Response memiliki status HTTP", function () {
    pm.expect(pm.response.code).to.be.a("number");
});

